CREATE TYPE "ProductStatus" AS ENUM ('uploaded','researching','needs_review','confirmed','listing_ready');
CREATE TYPE "JobStatus" AS ENUM ('queued','processing','completed','failed');
CREATE TYPE "VerificationStatus" AS ENUM ('verified','inferred','user_confirmed');
CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Workspace" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Workspace_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Membership" ("userId" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"role" TEXT NOT NULL DEFAULT 'owner',CONSTRAINT "Membership_pkey" PRIMARY KEY ("userId","workspaceId"));
CREATE TABLE "Product" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"status" "ProductStatus" NOT NULL DEFAULT 'uploaded',"confirmedCandidateId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Product_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductImage" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"name" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProductImage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductAttribute" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"name" TEXT NOT NULL,"value" TEXT NOT NULL,"status" "VerificationStatus" NOT NULL,"method" TEXT,"confidence" DOUBLE PRECISION,"evidenceJson" JSONB,CONSTRAINT "ProductAttribute_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ResearchJob" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"status" "JobStatus" NOT NULL DEFAULT 'queued',"provider" TEXT,"queryJson" JSONB,"error" TEXT,"attempts" INTEGER NOT NULL DEFAULT 0,"queuedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),CONSTRAINT "ResearchJob_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ResearchCandidate" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"researchJobId" TEXT NOT NULL,"title" TEXT NOT NULL,"sourceName" TEXT NOT NULL,"sourceUrl" TEXT NOT NULL,"productUrl" TEXT,"imageUrl" TEXT,"price" DOUBLE PRECISION,"currency" TEXT,"brand" TEXT,"specifications" JSONB NOT NULL,"matchingSignals" JSONB NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"status" "VerificationStatus" NOT NULL DEFAULT 'verified',CONSTRAINT "ResearchCandidate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Evidence" ("id" TEXT NOT NULL,"candidateId" TEXT NOT NULL,"sourceName" TEXT NOT NULL,"sourceUrl" TEXT NOT NULL,"excerpt" TEXT,"capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Evidence_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductListing" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"generatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProductListing_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ListingField" ("id" TEXT NOT NULL,"listingId" TEXT NOT NULL,"name" TEXT NOT NULL,"generatedValue" TEXT NOT NULL,"editedValue" TEXT,"status" TEXT NOT NULL DEFAULT 'generated',"generationId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ListingField_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Generation" ("id" TEXT NOT NULL,"listingId" TEXT NOT NULL,"fieldName" TEXT NOT NULL,"provider" TEXT,"model" TEXT,"instruction" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Generation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"userId" TEXT,"productId" TEXT,"action" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "ProductListing_productId_key" ON "ProductListing"("productId");
CREATE UNIQUE INDEX "ListingField_listingId_name_key" ON "ListingField"("listingId","name");
CREATE INDEX "Product_workspaceId_createdAt_idx" ON "Product"("workspaceId","createdAt");
CREATE INDEX "AuditLog_workspaceId_createdAt_idx" ON "AuditLog"("workspaceId","createdAt");
ALTER TABLE "Membership" ADD CONSTRAINT "Membership_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Membership" ADD CONSTRAINT "Membership_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Product" ADD CONSTRAINT "Product_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProductImage" ADD CONSTRAINT "ProductImage_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProductAttribute" ADD CONSTRAINT "ProductAttribute_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ResearchJob" ADD CONSTRAINT "ResearchJob_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ResearchCandidate" ADD CONSTRAINT "ResearchCandidate_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ResearchCandidate" ADD CONSTRAINT "ResearchCandidate_researchJobId_fkey" FOREIGN KEY ("researchJobId") REFERENCES "ResearchJob"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Evidence" ADD CONSTRAINT "Evidence_candidateId_fkey" FOREIGN KEY ("candidateId") REFERENCES "ResearchCandidate"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProductListing" ADD CONSTRAINT "ProductListing_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ListingField" ADD CONSTRAINT "ListingField_listingId_fkey" FOREIGN KEY ("listingId") REFERENCES "ProductListing"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Generation" ADD CONSTRAINT "Generation_listingId_fkey" FOREIGN KEY ("listingId") REFERENCES "ProductListing"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ListingField" ADD CONSTRAINT "ListingField_generationId_fkey" FOREIGN KEY ("generationId") REFERENCES "Generation"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL ON UPDATE CASCADE;
